def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    old = {"id": "a", "day": 3, "converted": True}
    latest = {"id": "a", "day": 1, "converted": False}
    same_day = {"id": "b", "day": 1, "converted": True}
    later_day = {"id": "0", "day": 2, "converted": True}
    assert dedupe_sessions([old, later_day, same_day, latest]) == [latest, same_day, later_day]


